    public KeyAgreeRecipientIdentifierKind Kind { get; private set; }
    public IssuerAndSerialNumber? IssuerAndSerialNumber { get; private set; }
    public RecipientKeyIdentifier? RKeyId { get; private set; }

    public static KeyAgreeRecipientIdentifier FromIssuerAndSerialNumber(IssuerAndSerialNumber issuerAndSerialNumber) => new KeyAgreeRecipientIdentifier
    {
        Kind = KeyAgreeRecipientIdentifierKind.IssuerAndSerialNumber,
        IssuerAndSerialNumber = issuerAndSerialNumber,
    };

    public static KeyAgreeRecipientIdentifier FromRKeyId(RecipientKeyIdentifier rKeyId) => new KeyAgreeRecipientIdentifier
    {
        Kind = KeyAgreeRecipientIdentifierKind.RKeyId,
        RKeyId = rKeyId,
    };

    public override string ToString()
    {
        return Kind switch
        {
            KeyAgreeRecipientIdentifierKind.IssuerAndSerialNumber => Asn1Formatting.Format(IssuerAndSerialNumber),
            KeyAgreeRecipientIdentifierKind.RKeyId => Asn1Formatting.Format(RKeyId),
            _ => "<unset>",
        };
    }

    public void Encode(Asn1Writer writer)
    {
        switch (Kind)
        {
            case KeyAgreeRecipientIdentifierKind.IssuerAndSerialNumber:
                IssuerAndSerialNumber.Encode(writer, Asn1Tag.Sequence);
                break;
            case KeyAgreeRecipientIdentifierKind.RKeyId:
                RKeyId.Encode(writer, new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true));
                break;
            default: throw new Asn1Exception("CHOICE has no alternative.");
        }
    }

    public static KeyAgreeRecipientIdentifier Decode(Asn1Reader reader)
    {
        if (!reader.TryPeekTag(out var peeked)) throw new Asn1Exception("Empty CHOICE.");
        var value = new KeyAgreeRecipientIdentifier();
        if (peeked.MatchesIgnoreConstructed(Asn1Tag.Sequence))
        {
            value.Kind = KeyAgreeRecipientIdentifierKind.IssuerAndSerialNumber;
            value.IssuerAndSerialNumber = Asn1Kit.Modern.CryptographicMessageSyntax2010.IssuerAndSerialNumber.Decode(reader, Asn1Tag.Sequence);
        }
        else if (peeked.MatchesIgnoreConstructed(new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true)))
        {
            value.Kind = KeyAgreeRecipientIdentifierKind.RKeyId;
            value.RKeyId = Asn1Kit.Modern.CryptographicMessageSyntax2010.RecipientKeyIdentifier.Decode(reader, new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true));
        }
        else throw new Asn1Exception("Unknown CHOICE alternative.");
        return value;
    }
}

